import{readDoorAnimations}from'./door-animation.js';
export const TRANSITIONS=[[0x69,'Animated door'],[0x67,'Step warp / fade'],[0x65,'Exit south / down'],[0x64,'Exit north / up'],[0x63,'Exit west / left'],[0x62,'Exit east / right']];
export function doorTransitionControls(api,runtime={},prefix='doorTransition'){
 let styles=[],reason='Open the source ROM to choose native opening frames.';try{const s=api.session?.();if(s){const n=readDoorAnimations(s.reader,s.id);styles=[...n.doors,...Object.entries(api.project().doorAnimations?.[s.id]?.doors||{}).filter(([id])=>+id>=n.doors.length).map(([id,d])=>({...d,id:+id}))];reason='';}}catch(e){reason=e.message;}
 return['Entrance','Return'].map((label,i)=>{const behavior=runtime[i?'nativeReturnBehavior':'nativeBehavior'],style=runtime[i?'nativeReturnDoorStyle':'nativeDoorStyle'];return`<label>${label} transition<select id="${prefix}Behavior${i}"><option value="">Keep source tile / automatic</option>${TRANSITIONS.map(([id,name])=>`<option value="${id}" ${behavior===id?'selected':''}>${name}</option>`).join('')}</select></label><label>${label} opening frames<select id="${prefix}Style${i}" ${styles.length?'':'disabled'}><option value="">Keep matching native frames</option>${styles.map(d=>`<option value="${d.id}" ${style===d.id?'selected':''}>${api.esc(d.name)} · tile ${d.metatile.toString(16)}</option>`).join('')}</select></label>`;}).join('')+(reason?`<p class="hint-line">${api.esc(reason)}</p>`:'')+'<p class="hint-line">Opening frames enable an animated door for that direction only. Interior exits can keep their normal exit step. Arrival facing is a separate setting.</p>';
}
export function readDoorTransitionControls(root,runtime,prefix='doorTransition'){
 const r={...runtime};for(let i=0;i<2;i++){const behaviorKey=i?'nativeReturnBehavior':'nativeBehavior',styleKey=i?'nativeReturnDoorStyle':'nativeDoorStyle',b=root.querySelector('#'+prefix+'Behavior'+i)?.value,s=root.querySelector('#'+prefix+'Style'+i);if(b!==undefined){if(b==='')delete r[behaviorKey];else r[behaviorKey]=+b;}if(s&&!s.disabled){if(s.value==='')delete r[styleKey];else{r[styleKey]=+s.value;r[behaviorKey]=0x69;}}}return r;
}
